import test from 'node:test';
import assert from 'node:assert/strict';
import { permit } from './limit.mjs';

test('allows inclusive Count values at the permitted boundaries', () => {
  assert.equal(permit(0), true);
  assert.equal(permit(3), true);
});

test('rejects Counts outside the inclusive 0 through 3 range', () => {
  assert.equal(permit(-1), false);
  assert.equal(permit(4), false);
});

test('rejects malformed non-Count inputs without coercion or exception', () => {
  for (const value of ['3', null, Number.NaN, 1.5]) {
    assert.equal(permit(value), false);
  }
});

